import{_ as o,l as n,o as e,c as i,v as t,p as l,x as s,d,i as c,S as p}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"任播与边缘","description":"","frontmatter":{"title":"任播与边缘","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/anycast-edge.md","filePath":"cs/anycast-edge.md","lastUpdated":1789023840000}'),h={name:"cs/anycast-edge.md"};function E(P,a,_,B,m,A){const r=n("Mermaid");return e(),i("div",null,[a[1]||(a[1]=t('<h1 id="任播与边缘" tabindex="-1">任播与边缘 <a class="header-anchor" href="#任播与边缘" aria-label="Permalink to &quot;任播与边缘&quot;">​</a></h1><div class="epigraph"><p>同一前缀从多处宣告，分组被路由到「最近」的实例；CDN 用它把用户送到边上的缓存节点。</p><footer>—— 据 Kurose and Ross；对照 RFC 4786 对任播操作的讨论；Nygren 等对 CDN</footer></div><p><a href="/cs/cdn-intuition">上一课</a>给出边缓存与请求导向。本课不重讲为何复制对象。缺口是导向手段之一：<strong>任播</strong>——多点宣告同一地址，靠 <a href="/cs/bgp-policy">BGP</a> 与 <a href="/cs/lpm">LPM</a> 把用户送进最近的 PoP。DNS 导向是另一手段，上一课已点名。本课不把套接字 API 提前。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>CDN 直觉留下「DNS 或任播」。DNS 按解析器位置返回不同 A/AAAA，粒度是解析器不是客户。任播：边缘节点共享前缀，路由自然选近。TCP 连接必须粘在同一实例上：路径变化会把后续段送到另一台没有状态的机器。缺口是<strong>用路由当负载均衡</strong>及其与有状态传输的张力。</p><p><span class="marginnote">无状态的 UDP DNS 很适合任播。HTTPS 依赖稳定路径或把状态同步到任播集合——工程上常「任播到 PoP，PoP 内再用本地负载均衡」。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>运营商在多地宣告同一覆盖前缀。用户的 SYN 到达某边缘，该边缘完成 <a href="/cs/tcp-handshake">TCP 握手</a> 与 <a href="/cs/http-tls-entry">TLS 入口</a>。缓存命中则本地答；未命中回源。故障时撤宣告，前缀收敛到活着的点。与单播对照：地址不再标识唯一主机，标识的是服务。</p>',8)),(e(),l(p,null,{default:s(()=>[c(r,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20USER%5B%22%E7%94%A8%E6%88%B7%E5%88%86%E7%BB%84%22%5D%20--%3E%20BGP%5B%22%E6%8C%89%E4%BB%BB%E6%92%AD%E5%89%8D%E7%BC%80%20LPM%22%5D%0A%20%20BGP%20--%3E%20EDGE%5B%22%E6%9C%80%E8%BF%91%E8%BE%B9%E7%BC%98%E5%AE%9E%E4%BE%8B%22%5D%0A%20%20EDGE%20--%3E%20HIT%5B%22%E7%BC%93%E5%AD%98%E5%91%BD%E4%B8%AD%22%5D%0A%20%20EDGE%20--%3E%20ORIGIN%5B%22%E5%9B%9E%E6%BA%90%22%5D%0A"})]),fallback:s(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>任播把控制平面政策变成「距离」上的选路，边缘把 <a href="/cs/http-semantics">HTTP 缓存头</a> 的允许落到地理上。它不提供新的端到端可靠性；路径漂移是任播的经典故障。安全：证书仍绑名字，不绑任播地址本身。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把全球 Anycast 的测量论文当必读，不引入把 TCP 状态在 PoP 间实时迁移的全部方案。应用如何拿到描述符并读写，下一课套接字 API。</p><p>后课默认：同一地址可以表示一群边缘。进程眼里的端点是套接字。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>任播靠路由把用户送到近处实例。</li><li>有状态传输要粘会话或把状态留在 PoP 内。</li><li>套接字 API 下一课。</li><li>出处：Kurose and Ross；RFC 4786；对照 CDN 文献。</li></ul>',7))])}const u=o(h,[["render",E]]);export{f as __pageData,u as default};
